        {
            new Quote { Id = "https://pl.wikiquote.org/wiki/Jarosław_Iwaszkiewicz", Text = "Dziwna sprawa ta młodość.", Author = "Jarosław Iwaszkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Jarosław_Iwaszkiewicz", Text = "Jeżeli nie można być świętą, to lepiej już być potępioną.", Author = "Jarosław Iwaszkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Jarosław_Iwaszkiewicz", Text = "Ogarnęła go tęsknota do tych czasów, kiedy żadna z ogromnych myśli, które teraz biły się w jego głowie, nie przeszkadzała mu do pełna doznawać życia, świata, Boga, miłości.", Author = "Jarosław Iwaszkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Jarosław_Iwaszkiewicz", Text = "Nie ma większego grzechu niż uważać, że wszystko jest jasne i zrozumiałe. Jest to grzech dumy i zaufania do siebie, który chciała popełnić Ewa, gdy pragnęła być bogom równa.", Author = "Jarosław Iwaszkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Jarosław_Iwaszkiewicz", Text = "Wierzysz w potęgę miłości, napełnia cię ona do tego stopnia, że nie zostawia miejsca na pytania. I dobrze tak jest. Bo skoro dopuścisz do jednego pytania, jednej wątpliwości, pustka zacznie wkradać się do twojego serca.", Author = "Jarosław Iwaszkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Jarosław_Iwaszkiewicz", Text = "Nikt nikogo jeszcze nie uratował. Sam się człowiek też nie uratuje.", Author = "Jarosław Iwaszkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Jarosław_Iwaszkiewicz", Text = "Pomyśl, Kostek, ja mam dwadzieścia pięć lat. Powtórz za mną, no, powtarzaj: dwadzieścia pięć lat! Ty rozumiesz, co to jest dwadzieścia pięć lat? Mnie się zdaje, że ja jestem stary, ale to jest młodość, rozumiesz przecie, młodość. A ja jeszcze nie żyłem. I co, nigdy żyć nie będę?", Author = "Jarosław Iwaszkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Jarosław_Iwaszkiewicz", Text = "Taka skromna była całe życie, a umiera jak Beethoven. W burzę.", Author = "Jarosław Iwaszkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Jarosław_Iwaszkiewicz", Text = "Teraz jednak pojął, że wszystko musi utonąć w przepaści lat minionych i nigdy już nie będzie wyjaśnione.", Author = "Jarosław Iwaszkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Jarosław_Iwaszkiewicz", Text = "Sztuka rządzenia polega na umiejętności przystosowania się do warunków.", Author = "Jarosław Iwaszkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Jarosław_Iwaszkiewicz", Text = "Całe życie śpię w za krótkim łóżku i kąpię się w za ciasnej wannie. Dosłownie i w przenośni.", Author = "Jarosław Iwaszkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Jarosław_Iwaszkiewicz", Text = "Ale noc zawsze dzień przesila, Nic nigdy ziemi nie przeraża, Pole kłosami się pochyla, Niebo gwiazdami się rozżarza.", Author = "Jarosław Iwaszkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Jarosław_Iwaszkiewicz", Text = "Smugi jasne, smugi srebrne, smugi szare, Srebrnowłose, srebrnodźwiękie, ukochane (…).", Author = "Jarosław Iwaszkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Jarosław_Iwaszkiewicz", Text = "Jak kroplę czuć na wardze smak każdej chwili Rozcinać mocnym nożem welinu białej kartki…", Author = "Jarosław Iwaszkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Jarosław_Iwaszkiewicz", Text = "Nie dla nas winnic modry stok I winnic wdzięk, i winnic sok, A dla nas pylny owsa łan I karczmarz Żyd, i wódki dzban.", Author = "Jarosław Iwaszkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Jarosław_Iwaszkiewicz", Text = "Nim przyjdzie wiosna, nim miną mrozy, w ciszy kolebce – nade mną sosna nade mną brzoza witkami szepce.", Author = "Jarosław Iwaszkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Jarosław_Iwaszkiewicz", Text = "Wszystko jest bez sensu, Wszystko pogmatwane, Jak te winorośle, Gąszcze cmentarniane.", Author = "Jarosław Iwaszkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Jarosław_Iwaszkiewicz", Text = "Wzywają mnie mej drogi ścieżki pogmatwane. Samotności wieczystej tajemne potęgi Mówią, że nie zbuduję, co nie zbudowane.", Author = "Jarosław Iwaszkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Jarosław_Iwaszkiewicz", Text = "Za tysiąc lat wszystkie kopuły czas wyrówna i nikt nie będzie znał już naszych imion", Author = "Jarosław Iwaszkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Jarosław_Iwaszkiewicz", Text = "Kocham książkę dlatego, że wprowadza mnie w mój własny świat, że odkrywa we mnie bogactwa, których nie przeczuwałem.", Author = "Jarosław Iwaszkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Jarosław_Iwaszkiewicz", Text = "Nie bądź dumna ze swego szczęścia. Szczęście jest zawsze krótkotrwałe. Ale nurzaj się w chwilach dzisiejszych jak w chłodnych falach wiecznych źródeł.", Author = "Jarosław Iwaszkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Jarosław_Iwaszkiewicz", Text = "Polacy są zbyt inteligentni jak na swe położenie geograficzne.", Author = "Jarosław Iwaszkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Jarosław_Iwaszkiewicz", Text = "Szczęście jest wówczas pełne, gdy światło poranku budzi dwoje ludzi do dnia pełnego wspólnych czynów i rozmów.", Author = "Jarosław Iwaszkiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Jarosław_Iwaszkiewicz", Text = "Za książką kryje się autor. Jego pisanie jest więc zawsze listem do czytelnika. Piszemy zazwyczaj listy do przyjaciół. Książka jest listem autora do przyjaciela.", Author = "Jarosław Iwaszkiewicz" },
